Íme egy teljes, „minden benne van” jellegű Exa AI Python integrációs példa, amely bemutatja a kulcsfunkciókat: keresés (neural/keyword/auto), dátum és domainszűrés, tartalomlekérés és opciók, hasonló oldalak keresése, válaszgenerálás streaminggel, valamint kutatási feladat JSONsémával, továbbá opcionális LangChain retriever integráció. A kód egyetlen futtatható szkriptbe van szervezve, környezeti változóból veszi az EXA_API_KEYt, és CLI paraméterekkel kapcsolhatók a demók.

 Rövid válasz
A lentebbi Python szkript megmutatja, hogyan lehet az Exa hivatalos Pythoncsomagjával teljes integrációt készíteni: inicializálás, keresések, tartalomlekérés, hasonlósági keresés, válasz és streamelt válasz, kutatási task sémával, plusz egy LangChaines retriever példa. [1][2][3]

 Teljes példa kód
 A kód az exapy hivatalos csomagra épül, a funkciók a GitHub READMEben dokumentált hívásokat követik. [1]
 A végén opcionális LangChain integráció látható az ExaSearchRetrieverrel, amely fejlettebb RAG workflowkhoz jó. [3]

python
#!/usr/bin/env python3
import os
import sys
import json
import argparse
from typing import Any, Dict, List, Optional

# pip install exa_py
from exa_py import Exa

# Opcionális: pip install langchain_exa
try:
    from langchain_exa import ExaSearchRetriever
    HAS_LANGCHAIN_EXA = True
except Exception:
    HAS_LANGCHAIN_EXA = False


def require_api_key() -> str:
    api_key = os.getenv("EXA_API_KEY")
    if not api_key:
        print("Hiba: Állítsd be az EXA_API_KEY környezeti változót!", file=sys.stderr)
        sys.exit(1)
    return api_key


def init_exa() -> Exa:
    api_key = require_api_key()
    exa = Exa(api_key=api_key)
    return exa


def demo_basic_search(exa: Exa, query: str = "Latest LLM reasoning benchmarks") -> Dict[str, Any]:
    # Alap keresés (neural by default / auto) [1][8]
    results = exa.search(query)
    return {"query": query, "results": [r.__dict__ if hasattr(r, "__dict__") else r for r in results]}


def demo_keyword_search_with_filters(
    exa: Exa,
    query: str = "vector database benchmarks",
    start: str = "2024-01-01",
    end: str = "2025-12-31",
    include_domains: Optional[List[str]] = None,
    exclude_domains: Optional[List[str]] = None,
) -> Dict[str, Any]:
    # Keyword típus, dátum és domain szűrők [1][8]
    results = exa.search(
        query,
        type="keyword",
        start_published_date=start,
        end_published_date=end,
        include_domains=include_domains or ["www.arxiv.org", "www.pinecone.io", "www.weaviate.io"],
        exclude_domains=exclude_domains or [],
    )
    return {"query": query, "results": [r.__dict__ if hasattr(r, "__dict__") else r for r in results]}


def demo_search_and_contents(
    exa: Exa,
    query: str = "structured reasoning with chain of thought",
) -> Dict[str, Any]:
    # Keresés + teljes szöveg lekérése opciókkal [1][8]
    results = exa.search_and_contents(
        query,
        text={"include_html_tags": False, "max_characters": 2000},  # tisztított szöveg, limitált hossz
        summary={"query": "Provide a concise 1-2 sentence summary for RAG pre-processing."},
    )
    # results elemei tipikusan dict-szerűek (SDK verziótól függhet a reprezentáció)
    def to_dict(x):
        try:
            return x.__dict__
        except Exception:
            return x
    return {"query": query, "results": [to_dict(r) for r in results]}


def demo_get_contents(exa: Exa, urls: List[str]) -> Dict[str, Any]:
    # Közvetlen tartalomlekérés URL-listához [1][8]
    results = exa.get_contents(
        urls,
        text={"include_html_tags": False, "max_characters": 3000},
        summary={"query": "Summarize main claims and evidence in 3 bullet points."},
    )
    def to_dict(x):
        try:
            return x.__dict__
        except Exception:
            return x
    return {"urls": urls, "results": [to_dict(r) for r in results]}


def demo_find_similar(exa: Exa, url: str) -> Dict[str, Any]:
    # Hasonló dokumentumok keresése [1][8]
    sims = exa.find_similar(url, exclude_source_domain=True)
    def to_dict(x):
        try:
            return x.__dict__
        except Exception:
            return x
    return {"seed_url": url, "results": [to_dict(s) for s in sims]}


def demo_find_similar_and_contents(exa: Exa, url: str) -> Dict[str, Any]:
    # Hasonló + azonnali tartalom [1][8]
    sims = exa.find_similar_and_contents(url, text=True)
    def to_dict(x):
        try:
            return x.__dict__
        except Exception:
            return x
    return {"seed_url": url, "results": [to_dict(s) for s in sims]}


def demo_answer(exa: Exa, question: str) -> Dict[str, Any]:
    # Egyszerű válasz (LLM-informed answer az Exa-ból) [1][8]
    resp = exa.answer(question, text=True)  # text=True: források tartalmát is felhasználhatja
    # A válasz objektum szerkezete SDK-verziótól függ; általánosított konverzió
    try:
        payload = resp.__dict__
    except Exception:
        payload = resp
    return {"question": question, "answer": payload}


def demo_stream_answer(exa: Exa, question: str) -> Dict[str, Any]:
    # Streaming válasz (chunk-onként) [1][8]
    stream_chunks = []
    for chunk in exa.stream_answer(question):
        # Itt nyomtatni is lehetne azonnal; most gyűjtjük
        stream_chunks.append(str(chunk))
    return {"question": question, "stream": stream_chunks}


def demo_research_task(exa: Exa) -> Dict[str, Any]:
    # Strukturált kutatási feladat JSON-sémával [1][8]
    QUESTION = (
        "Summarize the history of San Francisco highlighting one or two major events "
        "for each decade from 1850 to 1950"
    )
    OUTPUT_SCHEMA: Dict[str, Any] = {
        "type": "object",
        "required": ["timeline"],
        "properties": {
            "timeline": {
                "type": "array",
                "items": {
                    "type": "object",
                    "required": ["decade", "notableEvents"],
                    "properties": {
                        "decade": {"type": "string", "description": 'Decade label e.g. "1850s"'},
                        "notableEvents": {"type": "string", "description": "A summary of notable events."},
                    },
                },
            }
        },
    }
    task = exa.research.create_task(
        instructions=QUESTION,
        model="exa-research",
        output_schema=OUTPUT_SCHEMA,
    )
    try:
        payload = task.__dict__
    except Exception:
        payload = task
    return {"instructions": QUESTION, "task": payload}


def demo_langchain_exa(query: str = "Latest developments in quantum computing") -> Dict[str, Any]:
    # Opcionális: LangChain Exa retriever (ha telepítve van) [3]
    if not HAS_LANGCHAIN_EXA:
        return {"error": "langchain_exa nem elérhető. Telepítsd: pip install langchain_exa"}

    retriever = ExaSearchRetriever(
        exa_api_key=os.environ["EXA_API_KEY"],
        k=10,
        type="auto",               # "neural" | "keyword" | "auto"
        livecrawl="fallback",      # "always" | "fallback" | "never"
        text_contents_options={"max_characters": 3000},
        summary={"query": "generate one line summary in simple words."},
    )
    docs = retriever.invoke(query)
    # docs tipikusan LangChain Document objektumok
    out = []
    for d in docs:
        out.append({
            "page_content": d.page_content[:300] + ("..." if len(d.page_content) > 300 else ""),
            "metadata": d.metadata,
        })
    return {"query": query, "docs": out}


def main():
    parser = argparse.ArgumentParser(description="Exa AI full Python integration demo")
    parser.add_argument("--mode",
                        choices=[
                            "basic",
                            "keyword",
                            "search_contents",
                            "get_contents",
                            "similar",
                            "similar_contents",
                            "answer",
                            "stream_answer",
                            "research",
                            "lc_exa"
                        ],
                        default="basic")
    parser.add_argument("--query", type=str, default=None)
    parser.add_argument("--urls", type=str, nargs="*", default=None)
    parser.add_argument("--url", type=str, default=None)
    args = parser.parse_args()

    exa = init_exa()

    if args.mode == "basic":
        payload = demo_basic_search(exa, args.query or "Latest LLM reasoning benchmarks")
    elif args.mode == "keyword":
        payload = demo_keyword_search_with_filters(exa, args.query or "vector database benchmarks")
    elif args.mode == "search_contents":
        payload = demo_search_and_contents(exa, args.query or "structured reasoning with chain of thought")
    elif args.mode == "get_contents":
        if not args.urls:
            print("--urls szükséges (egy vagy több URL)", file=sys.stderr)
            sys.exit(2)
        payload = demo_get_contents(exa, args.urls)
    elif args.mode == "similar":
        if not args.url:
            print("--url szükséges", file=sys.stderr)
            sys.exit(2)
        payload = demo_find_similar(exa, args.url)
    elif args.mode == "similar_contents":
        if not args.url:
            print("--url szükséges", file=sys.stderr)
            sys.exit(2)
        payload = demo_find_similar_and_contents(exa, args.url)
    elif args.mode == "answer":
        question = args.query or "What are the most cited safety techniques to reduce LLM hallucinations?"
        payload = demo_answer(exa, question)
    elif args.mode == "stream_answer":
        question = args.query or "Summarize key AI policy changes in the EU in 2025."
        payload = demo_stream_answer(exa, question)
    elif args.mode == "research":
        payload = demo_research_task(exa)
    elif args.mode == "lc_exa":
        payload = demo_langchain_exa(args.query or "Latest developments in quantum computing")
    else:
        payload = {"error": "Ismeretlen mód"}

    print(json.dumps(payload, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()



 Telepítés és futtatás
 Telepítés: pip install exa_py, opcionálisan pip install langchain_exa; EXA_API_KEY környezeti változó beállítása szükséges. [1][3]
 Példák futtatása:
   Alap keresés: python exa_full_demo.py mode basic [1]
   Keyword + szűrők: python exa_full_demo.py mode keyword query "vector database benchmarks" [1]
   Keresés + tartalom: python exa_full_demo.py mode search_contents query "structured reasoning with chain of thought" [1]
   Tartalom URLlistáról: python exa_full_demo.py mode get_contents urls   [1]
   Hasonlók: python exa_full_demo.py mode similar url  [1]
   Hasonlók + tartalom: python exa_full_demo.py mode similar_contents url  [1]
   Válasz: python exa_full_demo.py mode answer query "Top changes in EU AI Act 2025" [1]
   Streamelt válasz: python exa_full_demo.py mode stream_answer query "Recent M&A in AI chip startups" [1]
   Kutatási task: python exa_full_demo.py mode research [1]
   LangChain retriever: python exa_full_demo.py mode lc_exa query "Latest developments in quantum computing" [3]

